```go
package ledger

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

var locales = map[string]struct {
	dateFormat       string
	dateSeparator    string
	decimalSeparator string
	decimalGroup     string
	negativeSuffix   string
	positiveSuffix   string
	header           string
}{
	"en-US": {
		"01/02/2006", "/", ".", ",", "", " ",
		"Date       | Description               | Change",
	},
	"nl-NL": {
		"02-01-2006", "-", ",", ".", "-", " ",
		"Datum      | Omschrijving              | Verandering",
	},
}

var currencies = map[string]string{
	"USD": "$",
	"EUR": "€",
}

func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if _, ok := currencies[currency]; !ok {
		return "", fmt.Errorf("unsupported currency: %s", currency)
	}
	loc, ok := locales[locale]
	if !ok {
		return "", fmt.Errorf("unsupported locale: %s", locale)
	}
	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].Date < sorted[j].Date ||
			(sorted[i].Date == sorted[j].Date && sorted[i].Description < sorted[j].Description) ||
			(sorted[i].Date == sorted[j].Date && sorted[i].Description == sorted[j].Description && sorted[i].Change < sorted[j].Change)
	})
	var b strings.Builder
	b.WriteString(loc.header)
	b.WriteByte('\n')
	for _, e := range sorted {
		b.WriteString(formatEntry(e, currency, loc))
	}
	return b.String(), nil
}
```

