// Entry is a single line item in the ledger.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// locale describes how a ledger is rendered for a particular locale.
type locale struct {
	header           string
	dateLayout       string // time layout used to render entry dates
	decimalSeparator string // separates whole and fractional parts of an amount
	decimalGroup     string // groups the whole part of an amount into thousands
}

var locales = map[string]*locale{
	"en-US": {
		header:           "Date       | Description               | Change",
		dateLayout:       "01/02/2006",
		decimalSeparator: ".",
		decimalGroup:     ",",
	},
	"nl-NL": {
		header:           "Datum      | Omschrijving              | Verandering",
		dateLayout:       "02-01-2006",
		decimalSeparator: ",",
		decimalGroup:     ".",
	},
}

var currencies = map[string]string{
