// formatAmount renders an absolute cent amount with locale-specific grouping
// and decimal separators, e.g. 123456 -> "1,234.56" or "1.234,56".
func formatAmount(cents int, group, separator string) string {
	whole := strconv.Itoa(cents / 100)
	var b strings.Builder
	for i, r := range whole {
		if i > 0 && (len(whole)-i)%3 == 0 {
			b.WriteString(group)
		}
		b.WriteRune(r)
	}
	b.WriteString(separator)
	b.WriteString(fmt.Sprintf("%02d", cents%100))
	return b.String()
}
