```go
package ledger

// Change log for the refactoring of FormatLedger:
//
//  1. Replaced the hand-rolled bubble sort (with its m1/m2 boolean-to-int
//     map trick) with sort.Slice and an explicit date/description/change
//     comparison.
//  2. Removed the per-entry goroutines and unbuffered channel: lines were
//     always reassembled in index order, so the concurrency added no value
//     (and leaked goroutines when an entry was invalid).
//  3. Replaced the recursive empty-ledger call — used only to validate the
//     currency and locale — with direct validation up front.
//  4. Consolidated the duplicated en-US/nl-NL formatting logic into a
//     locale table and a currency table, plus shared helpers for the
//     amount, date and padding.
//  5. Replaced the manual date slicing with time.Parse/time.Format; this
//     also validates the date value (e.g. rejects month 13), not just its
//     shape.
//  6. Replaced the empty errors.New("") values with descriptive errors.

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

// Entry is a single line item in the ledger.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// locale describes how a ledger is rendered for a particular locale.
type locale struct {
	header           string
	dateLayout       string // time layout used to render entry dates
	decimalSeparator string // separates the whole and fractional parts of an amount
	decimalGroup     string // groups the whole part of an amount into thousands
	currencySuffix   string // separator between the currency symbol and the amount
	negativePrefix   string // prepended to a negative amount
	negativeSuffix   string // appended to a negative amount
	positiveSuffix   string // appended to a non-negative amount
}

var locales = map[string]*locale{
	"en-US": {
		header:           "Date       | Description               | Change",
		dateLayout:       "01/02/2006",
		decimalSeparator: ".",
		decimalGroup:     ",",
		negativePrefix:   "(",
		negativeSuffix:   ")",
		positiveSuffix:   " ",
	},
	"nl-NL": {
		header:           "Datum      | Omschrijving              | Verandering",
		dateLayout:       "02-01-2006",
		decimalSeparator: ",",
		decimalGroup:     ".",
		currencySuffix:   " ",
		negativeSuffix:   "-",
		positiveSuffix:   " ",
	},
}

var currencies = map[string]string{
	"USD": "$",
	"EUR": "€",
}

const (
	dateWidth        = 10
	descriptionWidth = 25
	changeWidth      = 13
)

// FormatLedger renders the entries as a formatted ledger for the given
// currency and locale. Entries are sorted by date, then description, then
// change; the input slice is not modified.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	symbol, ok := currencies[currency]
	if !ok {
		return "", fmt.Errorf("unsupported currency: %q", currency)
	}
	loc, ok := locales[locale]
	if !ok {
		return "", fmt.Errorf("unsupported locale: %q", locale)
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		a, b := sorted[i], sorted[j]
		if a.Date != b.Date {
			return a.Date < b.Date
		}
		if a.Description != b.Description {
			return a.Description < b.Description
		}
		return a.Change < b.Change
	})

	var sb strings.Builder
	sb.WriteString(loc.header)
	sb.WriteByte('\n')
	for _, e := range sorted {
		line, err := formatEntry(e, symbol, loc)
		if err != nil {
			return "", err
		}
		sb.WriteString(line)
	}
	return sb.String(), nil
}

// formatEntry renders a single ledger line, validating the entry's date.
func formatEntry(e Entry, symbol string, loc *locale) (string, error) {
	t, err := time.Parse("2006-01-02", e.Date)
	if err != nil {
		return "", fmt.Errorf("invalid date %q: %v", e.Date, err)
	}
	return fmt.Sprintf("%s | %s | %s\n",
		padRight(t.Format(loc.dateLayout), dateWidth),
		padRight(truncate(e.Description, descriptionWidth), descriptionWidth),
		padLeft(loc.formatChange(symbol, e.Change), changeWidth)), nil
}

// formatChange renders the change cell, e.g. "($10.00)" or "$ 10,00 ".
func (l *locale) formatChange(symbol string, cents int) string {
	amount := formatAmount(abs(cents), l.decimalGroup, l.decimalSeparator)
	suffix := l.positiveSuffix
	if cents < 0 {
		return l.negativePrefix + symbol + l.currencySuffix + amount + l.negativeSuffix
	}
	return symbol + l.currencySuffix + amount + suffix
}

// formatAmount renders an absolute cent amount with grouping and a decimal
// separator, e.g. 123456 -> "1,234.56" or "1.234,56".
func formatAmount(cents int, group, separator string) string {
	whole := strconv.Itoa(cents / 100)
	var b strings.Builder
	for i, r := range whole {
		if i > 0 && (len(whole)-i)%3 == 0 {
			b.WriteString(group)
		}
		b.WriteRune(r)
	}
	b.WriteString(separator)
	b.WriteString(fmt.Sprintf("%02d", cents%100))
	return b.String()
}

func abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

// truncate shortens s to width by replacing the tail with an ellipsis.
func truncate(s string, width int) string {
	if len(s) > width {
		return s[:width-3] + "..."
	}
	return s
}

// padRight pads s with spaces on the right to width runes.
func padRight(s string, width int) string {
	if n := utf8.RuneCountInString(s); n < width {
		s += strings.Repeat(" ", width-n)
	}
	return s
}

// padLeft pads s with spaces on the left to width runes.
func padLeft(s string, width int) string {
	if n := utf8.RuneCountInString(s); n < width {
		s = strings.Repeat(" ", width-n) + s
	}
	return s
}
